"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["73500"],{68570(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.obrigatoriedade_invalida","status":422,"titulo":"A obrigatoriedade \xe9 SEMPRE ou NUNCA sem predicado, ou QUANDO com ele"},"descricao":{"codigo":"uniplus.formulario_portavel.obrigatoriedade_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio renderiz\xe1vel contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. A obrigatoriedade de um campo, de um grupo ou de um termo nas regras recebidas n\xe3o \xe9 coerente: o valor n\xe3o \xe9 `SEMPRE`, `NUNCA` nem `QUANDO` (inclusive o texto vazio), ou `SEMPRE` e `NUNCA` v\xeam com o predicado `predicadoObrigatoriedade`, ou `QUANDO` vem sem ele. A mensagem diz de quem \xe9 a obrigatoriedade: \\"A obrigatoriedade do campo \'`{c\xf3digo\\\\}`\' \xe9 SEMPRE ou NUNCA sem predicado, ou QUANDO com ele.\\", e do mesmo modo para o grupo e para o termo.","A recusa vem no corpo da resposta, com o c\xf3digo e o `detail` que traz a mensagem, sem lista `errors`. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, e a leitura para na primeira recusa, nesta ordem: o elemento nulo, as etapas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Use `SEMPRE` ou `NUNCA` sem `predicadoObrigatoriedade`, ou `QUANDO` com ele preenchido, e repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);